import React, { useEffect } from 'react';
import './AQIInputForm.css';

const AQIInputForm = ({ features, setFeatures, setResult }) => {
  const handleChange = (e) => {
    const updatedFeatures = {
      ...features,
      [e.target.name]: parseFloat(e.target.value),
    };
    setFeatures(updatedFeatures);
  };

  // Automatically call prediction API when features change
  useEffect(() => {
    const fetchPrediction = async () => {
      try {
        const res = await fetch('http://localhost:5000/predict', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(features),
        });
        const data = await res.json();
        setResult(data);
      } catch (err) {
        console.error('Prediction failed:', err);
      }
    };

    fetchPrediction();
  }, [features]); // runs every time features change

  return (
    <form className="aqi-input-form">
      <h3>📊 Predict Indoor AQI</h3>
      <table className="aqi-input-table">
        <tbody>
          {[
            ['PM2.5', 'PM2_5', 'µg/m³'],
            ['CO', 'CO', 'ppb'],
            ['NO2', 'NO2', 'ppb'],
            ['NH3', 'NH3', 'ppb'],
            ['O3', 'O3', 'ppb'],
            ['Temp (°C)', 'Temp', '°C'],
            ['Humidity (%)', 'Humidity', '%'],
            ['Pressure (hPa)', 'Pressure', 'hPa'],
          ].map(([label, name, unit]) => (
            <tr key={name}>
              <td className="label-cell">{label}</td>
              <td>
                <input
                  type="number"
                  name={name}
                  value={features[name]}
                  onChange={handleChange}
                  step="0.1"
                  required
                  className="input-cell"
                />
              </td>
              <td className="unit-cell">{unit}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </form>
  );
};

export default AQIInputForm;
